        if (tInterFrame > 1000 || tInterFrame < 0) tInterFrame = 1000;
        m_iSumSqFrameTime += tInterFrame * tInterFrame;
        m_iSumFrameTime += tInterFrame;
    }
    ++m_cFramesDrawn;
}
